pragma solidity ^0.8.36;
interface I { function f() external; } contract C { bytes4 constant A = this.f.selector; bytes4 constant B = I.f.selector; error E(); bytes4 constant D = E.selector; event V(); bytes32 constant F = V.selector; function f() external {} function g() external pure returns(bytes4, bytes4, bytes4, bytes32) { return (A, B, D, F); } }
